// Package lru implements a fixed-capacity least-recently-used cache of
// string keys and values with O(1) expected-time operations.
package lru

// nilIdx marks the absence of a node link.
const nilIdx = -1

// node is an entry in the recency list. Nodes live in a slice arena and are
// linked by index, which keeps the list compact and avoids per-entry heap
// allocations for the links themselves.
type node struct {
	key, value string
	prev, next int32
}

// Cache is an LRU cache holding at most a fixed number of keys. The zero value
// is not usable; construct one with New. A Cache is not safe for concurrent use.
type Cache struct {
	capacity int
	index    map[string]int32
	nodes    []node
	head     int32 // most recently used
	tail     int32 // least recently used
	free     int32 // head of the free list, chained through node.next
}

// New returns an empty cache that holds at most capacity keys.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, min(capacity, 1<<16)),
		head:     nilIdx,
		tail:     nilIdx,
		free:     nilIdx,
	}
}

// Len reports the number of keys currently held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and whether it was present.
// A hit marks key as the most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Set stores value under key and marks key as the most recently used. If the
// cache then exceeds its capacity, the least recently used key is evicted.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		c.moveToFront(i)
		return
	}
	if len(c.index) >= c.capacity {
		c.evict()
	}
	i := c.alloc(key, value)
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

// evict removes the least recently used entry.
func (c *Cache) evict() {
	if c.tail != nilIdx {
		c.remove(c.tail)
	}
}

// remove unlinks node i, drops it from the index, and recycles its slot.
func (c *Cache) remove(i int32) {
	c.unlink(i)
	n := &c.nodes[i]
	delete(c.index, n.key)
	*n = node{next: c.free, prev: nilIdx}
	c.free = i
}

// alloc returns the index of a node slot initialized with key and value,
// reusing a freed slot when one is available.
func (c *Cache) alloc(key, value string) int32 {
	if c.free != nilIdx {
		i := c.free
		c.free = c.nodes[i].next
		c.nodes[i] = node{key: key, value: value, prev: nilIdx, next: nilIdx}
		return i
	}
	c.nodes = append(c.nodes, node{key: key, value: value, prev: nilIdx, next: nilIdx})
	return int32(len(c.nodes) - 1)
}

func (c *Cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int32) {
	n := &c.nodes[i]
	n.prev = nilIdx
	n.next = c.head
	if c.head != nilIdx {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int32) {
	n := &c.nodes[i]
	if n.prev != nilIdx {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIdx {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nilIdx, nilIdx
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len = %d; want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteAndReuse(t *testing.T) {
	c := New(3)
	c.Set("x", "1")
	if !c.Delete("x") {
		t.Fatal("Delete(x) = false; want true")
	}
	if c.Delete("x") {
		t.Fatal("second Delete(x) = true; want false")
	}
	if c.Len() != 0 {
		t.Fatalf("Len = %d; want 0", c.Len())
	}
	for _, k := range []string{"p", "q", "r", "s"} {
		c.Set(k, k)
	}
	if _, ok := c.Get("p"); ok {
		t.Fatal("p should have been evicted")
	}
	for _, k := range []string{"q", "r", "s"} {
		if v, ok := c.Get(k); !ok || v != k {
			t.Fatalf("Get(%s) = %q, %v", k, v, ok)
		}
	}
	if len(c.nodes) > 3 {
		t.Fatalf("arena grew to %d nodes; want <= 3", len(c.nodes))
	}
}

func TestCapacityOne(t *testing.T) {
	c := New(1)
	c.Set("a", "1")
	c.Set("b", "2")
	if _, ok := c.Get("a"); ok {
		t.Fatal("a should have been evicted")
	}
	if v, _ := c.Get("b"); v != "2" {
		t.Fatalf("Get(b) = %q; want 2", v)
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each following line is one of
// SET <key> <value>, GET <key>, DEL <key>, or SIZE.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(bufio.NewReaderSize(r, 1<<16))
	sc.Buffer(make([]byte, 0, 1<<16), 1<<20)
	out := bufio.NewWriterSize(w, 1<<16)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return fmt.Errorf("reading capacity: %w", err)
		}
		return nil // empty input: nothing to do
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", sc.Text())
	}
	cache := lru.New(capacity)

	for sc.Scan() {
		if err := execute(cache, bytes.TrimRight(sc.Bytes(), "\r"), out); err != nil {
			return err
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("reading input: %w", err)
	}
	return out.Flush()
}

// execute applies one command line to cache, writing any output to out.
// Blank or unrecognized lines are ignored.
func execute(cache *lru.Cache, line []byte, out *bufio.Writer) error {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !ok {
			return nil
		}
		cache.Set(string(key), string(value))
		return nil
	case "GET":
		v, ok := cache.Get(string(rest))
		if !ok {
			v = "NULL"
		}
		out.WriteString(v)
	case "DEL":
		if cache.Delete(string(rest)) {
			out.WriteByte('1')
		} else {
			out.WriteByte('0')
		}
	case "SIZE":
		out.WriteString(strconv.Itoa(cache.Len()))
	default:
		return nil
	}
	return out.WriteByte('\n')
}
